INSERT OR REPLACE INTO _counters (key, value) VALUES ('event', 900);

-- 2026-08 quality repair: remove generated status/participant boilerplate while
-- preserving every event row and keeping duration/status in structured columns.
UPDATE events
SET description = trim(substr(description, 1, instr(description, '本次由') - 1))
WHERE instr(description, '本次由') > 0;

-- These two meetings become observable only at S03.  The original seed rows are
-- retained as historical review records so the loaded row count never decreases.
UPDATE events
SET event_id = 'evt_pitch_retrospective_0616_052',
    summary = '六月客户提案复盘',
    description = '复盘上一轮客户反馈，会议纪要已归档。',
    location = '线上会议',
    start_dt = '2026-06-16T18:30:00+08:00',
    end_dt = '2026-06-16T19:10:00+08:00',
    status = 'confirmed',
    created_at = '2026-06-15T14:20:00+08:00',
    updated_at = '2026-06-16T19:15:00+08:00'
WHERE event_id = 'cal_pitch_meeting_0716';

UPDATE events
SET event_id = 'evt_pitch_materials_0617_052',
    summary = '提案素材归档检查',
    description = '确认授权图片和报价附件已进入项目档案。',
    location = '滨江办公室',
    start_dt = '2026-06-17T17:40:00+08:00',
    end_dt = '2026-06-17T18:20:00+08:00',
    status = 'confirmed',
    created_at = '2026-06-16T11:10:00+08:00',
    updated_at = '2026-06-17T18:25:00+08:00'
WHERE event_id = 'cal_pitch_meeting_0717';

-- Training/health/equipment events after the kickoff are Agent-owned state, not
-- seed answers.  Preserve the rows as historical context by moving them back
-- 120 days; work/family constraints and the registered camp date remain future.
UPDATE events
SET start_dt = strftime('%Y-%m-%dT%H:%M:%S+08:00', start_dt, '-120 days'),
    end_dt = strftime('%Y-%m-%dT%H:%M:%S+08:00', end_dt, '-120 days'),
    created_at = strftime('%Y-%m-%dT%H:%M:%S+08:00', created_at, '-120 days'),
    updated_at = strftime('%Y-%m-%dT%H:%M:%S+08:00', updated_at, '-120 days')
WHERE calendar_id IN ('cal_train','cal_health','cal_wx','cal_venue','cal_cost','cal_home','cal_social','cal_admin')
  AND start_dt > '2026-07-06T09:10:00+08:00';

-- 2026-08 second-pass manual-cat repair: calendar titles use stable recurring
-- business names; status, location, time and participants already have fields of
-- their own and must not be encoded as generated title slots.
UPDATE events
SET summary = trim(substr(summary, 1, instr(summary, '｜') - 1))
WHERE instr(summary, '｜') > 0;

DELETE FROM events WHERE start_dt > '2026-07-06T09:10:00+08:00';

-- t=0 is event-000 (2026-07-06 09:10+08:00); later calendar facts arrive
-- through ordered world releases.
DELETE FROM events WHERE start_dt > '2026-07-06T09:10:00+08:00';
